use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Tier {
    Free,
    Pro,
    Enterprise,
}

pub struct Pricing {
    discounts_pct: HashMap<Tier, u8>,
}

impl Pricing {
    pub fn new(discounts_pct: HashMap<Tier, u8>) -> Self {
        Self { discounts_pct }
    }
}

use std::path::PathBuf;

pub struct Store {
    pub path: PathBuf,
}

impl Store {
    pub fn new(path: PathBuf) -> Self {
        Self { path }
    }
}
